fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    let rows = arr.len();
    assert!(rows > 0, "matrix must have at least one row");
    let cols = arr[0].len();
    assert!(cols > 0, "matrix must have at least one column");

    // Ensure rectangular (all rows same length).
    for r in &arr {
        assert!(r.len() == cols, "all rows must have the same number of columns");
    }

    // Output has `cols` rows, each of length `rows`.
    let mut out = vec![vec![0i8; rows]; cols];

    for i in 0..rows {
        for j in 0..cols {
            out[j][i] = arr[i][j];
        }
    }

    out
}